-- ---- adhkar: Morning (1) --------------------------------------------------

-- Ayat al-Kursi
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (1, 1, 'Ayat al-Kursi', 'اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ', 'Allahu la ilaha illa Huwal-Hayyul-Qayyum. La ta''khudhuhu sinatun wa la nawm. Lahu ma fis-samawati wa ma fil-ard. Man dhal-ladhi yashfa''u ''indahu illa bi-idhnih. Ya''lamu ma bayna aydihim wa ma khalfahum, wa la yuhituna bi-shay''im-min ''ilmihi illa bima sha''. Wasi''a kursiyyuhus-samawati wal-ard, wa la ya''uduhu hifdhuhuma, wa Huwal-''Aliyyul-''Adhim.', 'Allah — there is no deity except Him, the Ever-Living, the Sustainer of existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.', 1, 1, NULL, 1, datetime('now'), datetime('now'));

-- The Three Quls
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (2, 1, 'Surah Al-Ikhlas', 'قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ', 'Qul huwallahu ahad. Allahus-Samad. Lam yalid wa lam yulad. Wa lam yakul-lahu kufuwan ahad.', 'Say: He is Allah, the One. Allah, the Eternal Refuge. He neither begets nor is born, nor is there to Him any equivalent.', 3, 2, NULL, 1, datetime('now'), datetime('now')),
 (3, 1, 'Surah Al-Falaq', 'قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِن شَرِّ مَا خَلَقَ ۝ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۝ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ', 'Qul a''udhu bi-rabbil-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharrin-naffathati fil-''uqad. Wa min sharri hasidin idha hasad.', 'Say: I seek refuge in the Lord of daybreak, from the evil of that which He created, and from the evil of darkness when it settles, and from the evil of the blowers in knots, and from the evil of an envier when he envies.', 3, 3, NULL, 1, datetime('now'), datetime('now')),
 (4, 1, 'Surah An-Nas', 'قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَٰهِ النَّاسِ ۝ مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ', 'Qul a''udhu bi-rabbin-nas. Malikin-nas. Ilahin-nas. Min sharril-waswasil-khannas. Alladhi yuwaswisu fi sudurin-nas. Minal-jinnati wan-nas.', 'Say: I seek refuge in the Lord of mankind, the Sovereign of mankind, the God of mankind, from the evil of the retreating whisperer who whispers in the breasts of mankind — from among the jinn and mankind.', 3, 4, NULL, 1, datetime('now'), datetime('now'));

-- Sayyid al-Istighfar
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (5, 1, 'Sayyid al-Istighfar', 'اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَٰهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي، فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', 'Allahumma anta Rabbi la ilaha illa ant. Khalaqtani wa ana ''abduk, wa ana ''ala ''ahdika wa wa''dika mastata''t. A''udhu bika min sharri ma sana''t. Abu''u laka bi-ni''matika ''alayya, wa abu''u bi-dhanbi, faghfir li fa-innahu la yaghfirudh-dhunuba illa ant.', 'O Allah, You are my Lord, there is no deity except You. You created me and I am Your servant, and I am upon Your covenant and promise as much as I am able. I seek refuge in You from the evil of what I have done. I acknowledge Your favour upon me, and I acknowledge my sin, so forgive me, for none forgives sins except You.', 1, 5, NULL, 1, datetime('now'), datetime('now'));

-- SubhanAllah wa bihamdihi
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (6, 1, 'SubhanAllah wa Bihamdihi', 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ', 'SubhanAllahi wa bihamdih.', 'Glory is to Allah and praise is to Him.', 100, 6, NULL, 1, datetime('now'), datetime('now'));

-- La ilaha illallah wahdahu
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (7, 1, 'La ilaha illallah wahdahu', 'لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', 'La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, wa Huwa ''ala kulli shay''in qadir.', 'There is no deity except Allah alone, without partner. His is the dominion and His is the praise, and He is over all things competent.', 10, 7, NULL, 1, datetime('now'), datetime('now'));

-- Bismillahi alladhi la yadurru
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (8, 1, 'Bismillahi alladhi la yadurru', 'بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ', 'Bismillahil-ladhi la yadurru ma''a-smihi shay''un fil-ardi wa la fis-sama'', wa Huwas-Sami''ul-''Alim.', 'In the name of Allah, with whose name nothing on earth or in the heavens can cause harm, and He is the All-Hearing, the All-Knowing.', 3, 8, NULL, 1, datetime('now'), datetime('now'));

-- HasbiyAllah
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (9, 1, 'HasbiyAllahu la ilaha illa Huwa', 'حَسْبِيَ اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ', 'HasbiyAllahu la ilaha illa Huwa, ''alayhi tawakkaltu, wa Huwa Rabbul-''Arshil-''Adhim.', 'Sufficient for me is Allah; there is no deity except Him. Upon Him I rely, and He is the Lord of the Great Throne.', 7, 9, NULL, 1, datetime('now'), datetime('now'));

-- Asbahna wa asbahal-mulku lillah
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (10, 1, 'Asbahna wa asbahal-mulku lillah', 'أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ', 'Asbahna wa asbahal-mulku lillah, wal-hamdu lillah, la ilaha illallahu wahdahu la sharika lah.', 'We have entered the morning and the dominion belongs to Allah, and all praise is for Allah. There is no deity except Allah alone, without partner.', 1, 10, NULL, 1, datetime('now'), datetime('now'));

-- Allahumma bika asbahna
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (11, 1, 'Allahumma bika asbahna', 'اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ', 'Allahumma bika asbahna, wa bika amsayna, wa bika nahya, wa bika namut, wa ilaykan-nushur.', 'O Allah, by You we enter the morning, and by You we enter the evening, and by You we live and by You we die, and to You is the resurrection.', 1, 11, NULL, 1, datetime('now'), datetime('now'));

-- Raditu billahi Rabban
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (12, 1, 'Raditu billahi Rabban', 'رَضِيتُ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ ﷺ نَبِيًّا', 'Raditu billahi Rabban, wa bil-Islami dinan, wa bi-Muhammadin sallallahu ''alayhi wa sallama nabiyya.', 'I am pleased with Allah as my Lord, with Islam as my religion, and with Muhammad ﷺ as my Prophet.', 3, 12, NULL, 1, datetime('now'), datetime('now'));

-- Allahumma inni as'alukal-'afwa wal-'afiyah
INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (13, 1, 'Allahumma inni as''alukal-''afwa wal-''afiyah', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِي وَدُنْيَايَ وَأَهْلِي وَمَالِي', 'Allahumma inni as''alukal-''afwa wal-''afiyah fid-dunya wal-akhirah. Allahumma inni as''alukal-''afwa wal-''afiyah fi dini wa dunyaya wa ahli wa mali.', 'O Allah, I ask You for pardon and wellbeing in this world and the Hereafter. O Allah, I ask You for pardon and wellbeing in my religion, my worldly affairs, my family, and my wealth.', 1, 13, NULL, 1, datetime('now'), datetime('now'));

-- ---- adhkar: Evening (2) --------------------------------------------------

INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (14, 2, 'Ayat al-Kursi', 'اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ', 'Allahu la ilaha illa Huwal-Hayyul-Qayyum. La ta''khudhuhu sinatun wa la nawm. Lahu ma fis-samawati wa ma fil-ard. Man dhal-ladhi yashfa''u ''indahu illa bi-idhnih. Ya''lamu ma bayna aydihim wa ma khalfahum, wa la yuhituna bi-shay''im-min ''ilmihi illa bima sha''. Wasi''a kursiyyuhus-samawati wal-ard, wa la ya''uduhu hifdhuhuma, wa Huwal-''Aliyyul-''Adhim.', 'Allah — there is no deity except Him, the Ever-Living, the Sustainer of existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.', 1, 1, NULL, 1, datetime('now'), datetime('now')),
 (15, 2, 'Surah Al-Ikhlas', 'قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ', 'Qul huwallahu ahad. Allahus-Samad. Lam yalid wa lam yulad. Wa lam yakul-lahu kufuwan ahad.', 'Say: He is Allah, the One. Allah, the Eternal Refuge. He neither begets nor is born, nor is there to Him any equivalent.', 3, 2, NULL, 1, datetime('now'), datetime('now')),
 (16, 2, 'Surah Al-Falaq', 'قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِن شَرِّ مَا خَلَقَ ۝ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۝ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ', 'Qul a''udhu bi-rabbil-falaq. Min sharri ma khalaq. Wa min sharri ghasiqin idha waqab. Wa min sharrin-naffathati fil-''uqad. Wa min sharri hasidin idha hasad.', 'Say: I seek refuge in the Lord of daybreak, from the evil of that which He created, and from the evil of darkness when it settles, and from the evil of the blowers in knots, and from the evil of an envier when he envies.', 3, 3, NULL, 1, datetime('now'), datetime('now')),
 (17, 2, 'Surah An-Nas', 'قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَٰهِ النَّاسِ ۝ مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ', 'Qul a''udhu bi-rabbin-nas. Malikin-nas. Ilahin-nas. Min sharril-waswasil-khannas. Alladhi yuwaswisu fi sudurin-nas. Minal-jinnati wan-nas.', 'Say: I seek refuge in the Lord of mankind, the Sovereign of mankind, the God of mankind, from the evil of the retreating whisperer who whispers in the breasts of mankind — from among the jinn and mankind.', 3, 4, NULL, 1, datetime('now'), datetime('now')),
 (18, 2, 'Amsayna wa amsal-mulku lillah', 'أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ', 'Amsayna wa amsal-mulku lillah, wal-hamdu lillah, la ilaha illallahu wahdahu la sharika lah.', 'We have entered the evening and the dominion belongs to Allah, and all praise is for Allah. There is no deity except Allah alone, without partner.', 1, 5, NULL, 1, datetime('now'), datetime('now')),
 (19, 2, 'A''udhu bikalimatillahit-tammat', 'أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ', 'A''udhu bikalimatillahit-tammati min sharri ma khalaq.', 'I seek refuge in the perfect words of Allah from the evil of what He created.', 3, 6, NULL, 1, datetime('now'), datetime('now'));

-- ---- adhkar: Post-Salah (3) ------------------------------------------------

INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (20, 3, 'SubhanAllah', 'سُبْحَانَ اللَّهِ', 'SubhanAllah.', 'Glory is to Allah.', 33, 1, NULL, 1, datetime('now'), datetime('now')),
 (21, 3, 'Alhamdulillah', 'الْحَمْدُ لِلَّهِ', 'Alhamdulillah.', 'All praise is for Allah.', 33, 2, NULL, 1, datetime('now'), datetime('now')),
 (22, 3, 'Allahu Akbar', 'اللَّهُ أَكْبَرُ', 'Allahu Akbar.', 'Allah is the Greatest.', 34, 3, NULL, 1, datetime('now'), datetime('now')),
 (23, 3, 'Ayat al-Kursi after prayer', 'اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ', 'Allahu la ilaha illa Huwal-Hayyul-Qayyum. La ta''khudhuhu sinatun wa la nawm. Lahu ma fis-samawati wa ma fil-ard. Man dhal-ladhi yashfa''u ''indahu illa bi-idhnih. Ya''lamu ma bayna aydihim wa ma khalfahum, wa la yuhituna bi-shay''im-min ''ilmihi illa bima sha''. Wasi''a kursiyyuhus-samawati wal-ard, wa la ya''uduhu hifdhuhuma, wa Huwal-''Aliyyul-''Adhim.', 'Allah — there is no deity except Him, the Ever-Living, the Sustainer of existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Kursi extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.', 1, 4, NULL, 1, datetime('now'), datetime('now')),
 (24, 3, 'La ilaha illallah after prayer', 'لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', 'La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, wa Huwa ''ala kulli shay''in qadir.', 'There is no deity except Allah alone, without partner. His is the dominion and His is the praise, and He is over all things competent.', 1, 5, NULL, 1, datetime('now'), datetime('now'));

-- ---- adhkar: Before Sleeping (4) -------------------------------------------

INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (25, 4, 'Bismika Allahumma amutu wa ahya', 'بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا', 'Bismika Allahumma amutu wa ahya.', 'In Your name, O Allah, I die and I live.', 1, 1, NULL, 1, datetime('now'), datetime('now')),
 (26, 4, 'Allahumma aslamtu nafsi ilayk', 'اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ', 'Allahumma aslamtu nafsi ilayk, wa fawwadtu amri ilayk, wa wajjahtu wajhi ilayk, wa alja''tu dhahri ilayk, raghbatan wa rahbatan ilayk. La malja''a wa la manja minka illa ilayk.', 'O Allah, I submit myself to You, entrust my affairs to You, turn my face to You, and lean my back upon You, in hope and fear of You. There is no refuge and no escape from You except to You.', 1, 2, NULL, 1, datetime('now'), datetime('now'));

-- ---- adhkar: Upon Waking (5) ----------------------------------------------

INSERT OR REPLACE INTO adhkar (id, category_id, title, arabic_text, transliteration, translation, repeat_count, sort_order, audio_url, is_active, created_at, updated_at) VALUES
 (27, 5, 'Alhamdulillahi alladhi ahyana', 'الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ', 'Alhamdulillahil-ladhi ahyana ba''da ma amatana wa ilayhin-nushur.', 'All praise is for Allah who gave us life after having taken it from us, and unto Him is the resurrection.', 1, 1, NULL, 1, datetime('now'), datetime('now')),
 (28, 5, 'La ilaha illallah upon waking', 'لَا إِلَٰهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ', 'La ilaha illallahu wahdahu la sharika lah, lahul-mulku wa lahul-hamd, wa Huwa ''ala kulli shay''in qadir.', 'There is no deity except Allah alone, without partner. His is the dominion and His is the praise, and He is over all things competent.', 1, 2, NULL, 1, datetime('now'), datetime('now'));

-- ---- adhkar_sources (references) ------------------------------------------

INSERT OR REPLACE INTO adhkar_sources (id, dhikr_id, source_type, collection, reference, source_text, verification_status, created_at) VALUES
 (1,  1,  'quran',  'Qur''an', 'Al-Baqarah 2:255', 'Reciting Ayat al-Kursi in the morning protects until evening (al-Hakim; graded authentic by al-Albani).', 'verified', datetime('now')),
 (2,  2,  'quran',  'Qur''an', 'Al-Ikhlas 112:1-4', 'The Three Quls recited three times morning and evening suffice as protection (Abu Dawud 5082; at-Tirmidhi 3575).', 'verified', datetime('now')),
 (3,  5,  'hadith', 'Sahih al-Bukhari', 'Bukhari 6306', 'Whoever says it in the morning with certainty and dies that day enters Paradise.', 'verified', datetime('now')),
 (4,  6,  'hadith', 'Sahih Muslim', 'Muslim 2692', 'Whoever says it one hundred times, his sins are forgiven even if they are like the foam of the sea.', 'verified', datetime('now')),
 (5,  7,  'hadith', 'Sahih al-Bukhari', 'Bukhari 3293 / Muslim 2691', 'Whoever says it ten times is like one who freed four slaves from the descendants of Ismail.', 'verified', datetime('now')),
 (6,  8,  'hadith', 'Sunan Abi Dawud', 'Abu Dawud 5088; at-Tirmidhi 3388', 'Whoever says it three times in the morning and evening, nothing will harm him.', 'verified', datetime('now')),
 (7,  9,  'hadith', 'Sunan Abi Dawud', 'Abu Dawud 5081', 'Whoever says it seven times morning and evening, Allah suffices him in his worries.', 'verified', datetime('now')),
 (8,  10, 'hadith', 'Sahih Muslim', 'Muslim 2723', 'The morning and evening supplications of the Prophet ﷺ.', 'verified', datetime('now')),
 (9,  12, 'hadith', 'Sunan Abi Dawud', 'Abu Dawud 5072; at-Tirmidhi 3389', 'Whoever says it three times morning and evening, it is a right upon Allah to please him on the Day of Resurrection.', 'verified', datetime('now')),
 (10, 13, 'hadith', 'Sunan Abi Dawud', 'Abu Dawud 5074', 'The Prophet ﷺ taught this comprehensive supplication for wellbeing.', 'verified', datetime('now')),
 (11, 19, 'hadith', 'Sahih Muslim', 'Muslim 2709', 'Whoever says it three times in the evening, no poison or harm will afflict him that night.', 'verified', datetime('now')),
 (12, 22, 'hadith', 'Sahih Muslim', 'Muslim 597', 'The tasbih after prayer: SubhanAllah 33, Alhamdulillah 33, Allahu Akbar 34.', 'verified', datetime('now')),
 (13, 25, 'hadith', 'Sahih al-Bukhari', 'Bukhari 6324', 'The Prophet ﷺ said this before sleeping.', 'verified', datetime('now')),
 (14, 26, 'hadith', 'Sahih al-Bukhari', 'Bukhari 247 / Muslim 2710', 'The Prophet ﷺ instructed to say this before sleeping.', 'verified', datetime('now')),
 (15, 27, 'hadith', 'Sahih al-Bukhari', 'Bukhari 6312', 'The Prophet ﷺ said this upon waking.', 'verified', datetime('now'));

-- ---- duas ------------------------------------------------------------------

INSERT OR REPLACE INTO duas (id, category_id, title, arabic_text, transliteration, translation, source_id, audio_url, sort_order, is_active, created_at, updated_at) VALUES
 (1, 6, 'Rabbi a''udhu bika min hamazatish-shayatin', 'رَبِّ أَعُوذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَعُوذُ بِكَ رَبِّ أَنْ يَحْضُرُونِ', 'Rabbi a''udhu bika min hamazatish-shayatin, wa a''udhu bika Rabbi an yahdurun.', 'My Lord, I seek refuge in You from the incitements of the devils, and I seek refuge in You, my Lord, lest they be present with me.', 1, NULL, 1, 1, datetime('now'), datetime('now')),
 (2, 6, 'Allahumma inni a''udhu bika minal-hammi wal-hazan', 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ', 'Allahumma inni a''udhu bika minal-hammi wal-hazan, wal-''ajzi wal-kasal, wal-bukhli wal-jubn, wa dala''id-dayni wa ghalabatir-rijal.', 'O Allah, I seek refuge in You from anxiety and sorrow, weakness and laziness, miserliness and cowardice, the burden of debts and the overpowering of men.', NULL, NULL, 2, 1, datetime('now'), datetime('now')),
 (3, 7, 'Sayyid al-Istighfar', 'اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَٰهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي، فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', 'Allahumma anta Rabbi la ilaha illa ant. Khalaqtani wa ana ''abduk, wa ana ''ala ''ahdika wa wa''dika mastata''t. A''udhu bika min sharri ma sana''t. Abu''u laka bi-ni''matika ''alayya, wa abu''u bi-dhanbi, faghfir li fa-innahu la yaghfirudh-dhunuba illa ant.', 'O Allah, You are my Lord, there is no deity except You. You created me and I am Your servant, and I am upon Your covenant and promise as much as I am able. I seek refuge in You from the evil of what I have done. I acknowledge Your favour upon me, and I acknowledge my sin, so forgive me, for none forgives sins except You.', NULL, NULL, 1, 1, datetime('now'), datetime('now')),
 (4, 7, 'Rabbana zalamna anfusana', 'رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ', 'Rabbana zalamna anfusana wa in lam taghfir lana wa tarhamna lanakunanna minal-khasirin.', 'Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers.', NULL, NULL, 2, 1, datetime('now'), datetime('now')),
 (5, 8, 'Ihdinas-siratal-mustaqim', 'اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ', 'Ihdinas-siratal-mustaqim.', 'Guide us to the straight path.', NULL, NULL, 1, 1, datetime('now'), datetime('now')),
 (6, 8, 'Ya Muqallibal-qulub', 'يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ', 'Ya Muqallibal-qulub, thabbit qalbi ''ala dinik.', 'O Turner of the hearts, keep my heart firm upon Your religion.', NULL, NULL, 2, 1, datetime('now'), datetime('now')),
 (7, 9, 'Rabbana hablana min azwajina', 'رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا', 'Rabbana hablana min azwajina wa dhurriyyatina qurrata a''yun, waj''alna lil-muttaqina imama.', 'Our Lord, grant us from among our spouses and offspring comfort to our eyes, and make us leaders for the righteous.', NULL, NULL, 1, 1, datetime('now'), datetime('now')),
 (8, 10, 'Dua of travel', 'اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ', 'Allahu Akbar, Allahu Akbar, Allahu Akbar. Subhanal-ladhi sakhkhara lana hadha wa ma kunna lahu muqrinin, wa inna ila Rabbina lamunqalibun.', 'Allah is the Greatest, Allah is the Greatest, Allah is the Greatest. Glory is to Him who has subjected this to us, and we could not have subdued it ourselves. And indeed we, to our Lord, will return.', NULL, NULL, 1, 1, datetime('now'), datetime('now')),
 (9, 11, 'Allahumma Rabban-nas adhhibil-ba''s', 'اللَّهُمَّ رَبَّ النَّاسِ، أَذْهِبِ الْبَأْسَ، اشْفِ أَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا', 'Allahumma Rabban-nas, adhhibil-ba''s, ishfi Antash-Shafi, la shifa''a illa shifa''uk, shifa''an la yughadiru saqama.', 'O Allah, Lord of mankind, remove the affliction and cure, for You are the Healer. There is no cure except Your cure — a cure that leaves no illness behind.', NULL, NULL, 1, 1, datetime('now'), datetime('now')),
 (10, 12, 'Allahumma inni as''aluka rizqan tayyiban', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا', 'Allahumma inni as''aluka ''ilman nafi''an, wa rizqan tayyiban, wa ''amalan mutaqabbala.', 'O Allah, I ask You for beneficial knowledge, good provision, and accepted deeds.', NULL, NULL, 1, 1, datetime('now'), datetime('now')),
 (11, 13, 'Rabbana afrigh ''alayna sabran', 'رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ', 'Rabbana afrigh ''alayna sabran wa thabbit aqdamana wansurna ''alal-qawmil-kafirin.', 'Our Lord, pour upon us patience, plant firmly our feet, and give us victory over the disbelieving people.', NULL, NULL, 1, 1, datetime('now'), datetime('now')),
 (12, 14, 'Rabbana atina fid-dunya hasanah', 'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ', 'Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina ''adhaban-nar.', 'Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.', NULL, NULL, 1, 1, datetime('now'), datetime('now')),
 (13, 14, 'Allahumma inni as''alukal-huda', 'اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى', 'Allahumma inni as''alukal-huda wat-tuqa wal-''afafa wal-ghina.', 'O Allah, I ask You for guidance, piety, chastity, and self-sufficiency.', NULL, NULL, 2, 1, datetime('now'), datetime('now'));